oxy_webhelp_navlinks = {"arch_viewing_arch_loc_dashboard-d39307e9456":{"topics":[{"title":"Archival locations dashboard","shortdesc":"<p class=\"shortdesc\">The archival location dashboard provides insights into your data center archival         locations. You can monitor storage growth over time, archival lag, and storage consumption         by workloads at each location on this dashboard.<\/p>","href":"saas\/arch_location_dashboard_info.html","attributes":{"data-id":"arch_location_dashboard_info"},"menu":{"hasChildren":false},"tocID":"arch_location_dashboard_info-d39307e9467","topics":[]},{"title":"Resolving archival lag","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> alerts you when archival lag builds up on a data center archival         location and recommends prioritized actions. Use the Resolving Archival Lag dialog box to         review and apply the recommendations that reduce lag before it affects backups and         recovery.<\/p>","href":"saas\/resolving_archival_lag.html","attributes":{"data-id":"resolving_archival_lag"},"menu":{"hasChildren":false},"tocID":"resolving_archival_lag-d39307e9478","topics":[]}]}};